// Generated by OSL (@osl/backend-hono-trpc-vite). The Messages page: a master list of Message rows and a detail pane for the selected one.
// Do not edit: this file is rewritten on every osl generate.

"use client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link, Outlet, useMatchRoute, useNavigate, useParams } from "@tanstack/react-router";
import { Plus } from "lucide-react";
import { Fragment, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Button, buttonVariants } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { client, sessionUser, type Inputs, type Outputs, type SessionUser } from "../client";
import { EmptyPane, ErrorNote, FieldRow, FormRow, ListSkeleton, Pagination, Pane, PaneHeader, PaneSkeleton, RowError, formatDateTime, selectClass, splitList, text } from "../ui";

type Row = Outputs["messages"]["list"]["data"][number];
type Detail = Outputs["messages"]["get"];
type Input<K extends keyof Inputs["messages"]> = Inputs["messages"][K];

const PAGE_SIZE = 20;
const KEY = ["messages"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return (user !== null && row.author_id === user.id && user !== null);
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return ((user !== null && row.author_id === user.id && user !== null) || user !== null);
}

/** Who may open this page */
function canOpen(user: SessionUser | null): boolean {
  return user !== null;
}

function AccessGate({ user }: { user: SessionUser | null }) {
  return (
    <div className="mx-auto max-w-md p-6">
      <Card>
        <CardHeader>
          <CardTitle>{user ? "No access" : "Sign in required"}</CardTitle>
          <CardDescription>{user ? "Your account cannot open this page." : "Sign in to open this page."}</CardDescription>
        </CardHeader>
        {user ? null : (
          <CardContent>
            <Link to="/login" className={buttonVariants()}>
              Sign in
            </Link>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

/** Waits for the session, then renders the page or the gate */
function guarded<P extends object>(Component: (props: P) => ReactNode) {
  return function Guarded(props: P) {
    const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
    if (session.isPending) return <PaneSkeleton />;
    const user = sessionUser(session.data);
    if (!canOpen(user)) return <AccessGate user={user} />;
    return <Component {...props} />;
  };
}

const MESSAGES_FIELDS = ["channel_id", "body"] as const;
type MessagesField = (typeof MESSAGES_FIELDS)[number];

type MessagesValues = {
  channel_id: string;
  body: string;
};

const EMPTY_MESSAGES: MessagesValues = {
  channel_id: "",
  body: ""
};

const MESSAGES_CREATE: readonly MessagesField[] = ["channel_id", "body"];

function toMessagesCreateInput(v: MessagesValues): Input<"create"> {
  return {
    channel_id: v.channel_id,
    body: v.body
  };
}

const MESSAGES_UPDATE: readonly MessagesField[] = ["channel_id", "body"];

function toMessagesUpdateInput(v: MessagesValues): Input<"update">["data"] {
  return {
    channel_id: v.channel_id,
    body: v.body
  };
}

function messagesFromRow(row: Detail): MessagesValues {
  return {
    channel_id: text(row.channel_id),
    body: text(row.body)
  };
}

/** Picks a Channel from the channels resource */
function ChannelIdPicker({
  id,
  value,
  onChange,
  allowEmpty
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  allowEmpty: boolean;
}) {
  const options = useQuery({ queryKey: ["channels", "list", { page_size: 200 }], queryFn: () => client.channels.list({ page_size: 200 }) });
  return (
    <select id={id} className={selectClass} value={value} onChange={e => onChange(e.target.value)}>
      {allowEmpty ? <option value="">—</option> : null}
      {(options.data?.data ?? []).map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.name)}
        </option>
      ))}
    </select>
  );
}

type MessagesSetter = <K extends keyof MessagesValues>(key: K, value: MessagesValues[K]) => void;

function renderMessagesField(field: MessagesField, values: MessagesValues, set: MessagesSetter) {
  switch (field) {
    case "channel_id":
      return (
      <FormRow label="Channel" htmlFor="channel_id">
        <ChannelIdPicker id="channel_id" value={values.channel_id} onChange={value => set("channel_id", value)} allowEmpty={false} />
      </FormRow>
      );
    case "body":
      return (
      <FormRow label="Body" htmlFor="body">
        <Textarea id="body" rows={4} value={values.body} onChange={e => set("body", e.target.value)} required />
      </FormRow>
      );
  }
}

function MessagesForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly MessagesField[];
  initial: MessagesValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: MessagesValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<MessagesValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: MessagesSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderMessagesField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

function MessagesLayoutInner() {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE } as Inputs["messages"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.messages.list(input) });
  const matchRoute = useMatchRoute();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Messages" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link to="/messages/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New message">
              <Plus />
            </Link>
          ) : null}
        </PaneHeader>


        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No messages yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    to="/messages/$id" params={{ id: text(row.id) }}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", Boolean(matchRoute({ to: "/messages/$id", params: { id: text(row.id) } })) && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.body) || "Message " + text(row.id)}</div>
                    <div className="truncate text-xs text-muted-foreground">{[text(row.channel_id)].filter(Boolean).join(" · ")}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        <Outlet />
      </section>
    </div>
  );
}

function MessagesIndexInner() {
  return <EmptyPane>Select a message from the list, or create one.</EmptyPane>;
}

function MessagesNewInner() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.messages.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/messages/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New message">
      <MessagesForm
        fields={MESSAGES_CREATE}
        initial={EMPTY_MESSAGES}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toMessagesCreateInput(values))}
      />
    </Pane>
  );
}

function MessagesDetailInner() {
  const { id: rawId } = useParams({ from: "/messages/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.messages.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["messages"]["update"]) => client.messages.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["messages"]["delete"]) => client.messages.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/messages" });
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <RowError error={query.error} signIn={<Link to="/login" className={buttonVariants()}>Sign in</Link>} />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.body) || "Message " + text(row.id)}
      actions={
        <>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this message?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <MessagesForm
          fields={MESSAGES_UPDATE}
          initial={messagesFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toMessagesUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Channel">{user !== null ? <Link to="/channels/$id" params={{ id: text(row.channel_id) }} className="hover:underline">{text(row.channel_id) || "—"}</Link> : text(row.channel_id) || "—"}</FieldRow>
        <FieldRow label="Author">{text(row.author_id) || "—"}</FieldRow>
        <FieldRow label="Body">
          <p className="whitespace-pre-wrap">{text(row.body) || "—"}</p>
        </FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const MessagesLayout = guarded(MessagesLayoutInner);
export const MessagesIndex = guarded(MessagesIndexInner);
export const MessagesNew = guarded(MessagesNewInner);
export const MessagesDetail = guarded(MessagesDetailInner);
